import { HttpError } from './errors.js'
import { query, type RequestCtx } from './db.js'
import { num } from './util.js'

/**
 * Auto-generated codes: product SKU `P00001`, customer code `C00001`, and in-store
 * EAN-13 barcodes in the GS1 restricted range `20xxxxxxxxxxC` (scannable, printable).
 * Each is "highest existing + 1"; unique indexes catch a concurrent clash and the
 * caller retries via `withCodeRetry`.
 */

const SKU_PREFIX = 'P'
const CUSTOMER_PREFIX = 'C'
const EAN_PREFIX = '20'

function pad(n: number, width: number): string {
  return String(n).padStart(width, '0')
}

/** EAN-13 check digit for the first 12 digits. */
export function ean13CheckDigit(first12: string): number {
  let sum = 0
  for (let i = 0; i < 12; i++) sum += Number(first12[i]) * (i % 2 === 0 ? 1 : 3)
  return (10 - (sum % 10)) % 10
}

export async function nextSku(ctx: RequestCtx): Promise<string> {
  const rows = await query(
    ctx,
    `SELECT COALESCE(MAX(substring(sku FROM '^${SKU_PREFIX}([0-9]{1,9})$')::bigint), 0) AS n FROM products`,
  )
  return `${SKU_PREFIX}${pad(num(rows[0] ?? {}, 'n') + 1, 5)}`
}

export async function nextBarcode(ctx: RequestCtx): Promise<string> {
  const rows = await query(
    ctx,
    `SELECT COALESCE(MAX(substring(barcode FROM '^${EAN_PREFIX}([0-9]{10})[0-9]$')::bigint), 0) AS n FROM products`,
  )
  const next = num(rows[0] ?? {}, 'n') + 1
  if (next > 9_999_999_999) throw new HttpError(409, 'เลขบาร์โค้ดภายในร้านเต็มแล้ว', 'barcode_exhausted')
  const body = `${EAN_PREFIX}${pad(next, 10)}`
  return `${body}${ean13CheckDigit(body)}`
}

export async function nextCustomerCode(ctx: RequestCtx): Promise<string> {
  const rows = await query(
    ctx,
    `SELECT COALESCE(MAX(substring(code FROM '^${CUSTOMER_PREFIX}([0-9]{1,9})$')::bigint), 0) AS n FROM customers`,
  )
  return `${CUSTOMER_PREFIX}${pad(num(rows[0] ?? {}, 'n') + 1, 5)}`
}

/**
 * Run `create` and, when it fails on a duplicate while a code was auto-generated,
 * try again with fresh codes (another terminal took the same number).
 */
export async function withCodeRetry<T>(autoGenerated: boolean, create: () => Promise<T>): Promise<T> {
  const attempts = autoGenerated ? 3 : 1
  for (let i = 1; ; i++) {
    try {
      return await create()
    } catch (err) {
      if (i >= attempts || !(err instanceof HttpError) || err.code !== 'duplicate') throw err
    }
  }
}
